//! 🧪️ A real failed Source allocation retains and returns its original paid inputs.
use semio_framework_job_context::*;
use semio_framework_value_control_contract::{RetainedAllocationEffect,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetainedWorkPoll,RetirementDemand,ValueError,ValueRefusalKind};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn step(bank:&mut EffectBank,demand:RetirementDemand,work:u64,run:impl FnOnce(&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome)->RetainedCloneStep{let issued=grant(demand);let((poll,actual),heap)=observe(||bank.run(issued,work,|effect|RetainedWorkPoll::Complete(run(effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("funded original birth remained pending")};let result=turn.result.unwrap();assert_eq!(actual,if demand.capacity_bytes==0{None}else{Some(demand.capacity_bytes)});bank.post(result.progress(),issued,heap);assert_eq!(bank.take_admitted(),Some(true));result}
#[test]fn source_allocator_failure_returns_the_same_paid_inputs(){
 let law:serde_json::Value=serde_json::from_str(include_str!("source-birth.json")).unwrap();let mut bank=EffectBank::new(Wallet::from_profile(&serde_json::json!({"items":128,"copyBytes":1048576,"capacityBytes":1048576,"releaseBytes":1048576,"depth":64,"fuel":256})));
 let mut payload=OriginalJobPayloadAdmission::new();step(&mut bank,OriginalJobPayloadAdmission::prepare_demand(),1,|e|payload.prepare(OperationId(9107),Generation(3),e));step(&mut bank,OriginalJobPayloadAdmission::backing_demand().unwrap(),OriginalJobPayloadAdmission::backing_work_demand(),|e|payload.admit_backing(e));step(&mut bank,OriginalJobPayloadAdmission::publication_demand().unwrap(),OriginalJobPayloadAdmission::publication_work_demand(),|e|payload.publish(e));let mut authority=None;step(&mut bank,OriginalJobPayloadAdmission::take_demand(),1,|e|payload.take_authority(&mut authority,e));assert!(payload.terminal_is_empty());let payload_identity=authority.as_ref().unwrap().identity().unwrap();
 let mut cancellation=OriginalCancelRootAdmission::new();step(&mut bank,OriginalCancelRootAdmission::prepare_demand(),1,|e|cancellation.prepare(e));step(&mut bank,OriginalCancelRootAdmission::backing_demand().unwrap(),OriginalCancelRootAdmission::backing_work_demand(),|e|cancellation.admit_backing(e));step(&mut bank,OriginalCancelRootAdmission::publication_demand().unwrap(),OriginalCancelRootAdmission::publication_work_demand(),|e|cancellation.publish(e));let mut token=None;step(&mut bank,OriginalCancelRootAdmission::take_demand(),1,|e|cancellation.take_token(&mut token,e));assert!(cancellation.terminal_is_empty());let cancel_identity=OriginalCancelRootAdmission::token_identity(token.as_ref().unwrap());
 let mut source=OriginalCallerSourceAdmission::new();let demand=OriginalCallerSourceAdmission::prepare_demand();let mut denied=grant(demand);denied.maximum_copy_bytes=0;let(poll,actual)=bank.run(denied,1,|e|RetainedWorkPoll::Complete(source.prepare(&mut authority,&mut token,e)));let RetainedWorkPoll::Complete(turn)=poll else{panic!("denied Source assembly pending")};assert_eq!(actual,None);assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),RetainedCloneProgress::default());assert_eq!(bank.take_admitted(),None);assert_eq!(authority.as_ref().unwrap().identity(),Some(payload_identity));assert_eq!(OriginalCancelRootAdmission::token_identity(token.as_ref().unwrap()),cancel_identity);
 step(&mut bank,demand,1,|e|source.prepare(&mut authority,&mut token,e));assert!(authority.is_none()&&token.is_none()&&source.has_roots());assert_eq!(source.payload_identity(),Some(payload_identity));assert_eq!(source.cancellation_identity(),Some(cancel_identity));let issued=grant(OriginalCallerSourceAdmission::backing_demand().unwrap());let remaining=bank.wallet().remaining();let work_before=bank.wallet().remaining_work();let(((poll,actual),attempts),heap)=observe(||refuse(||bank.run(issued,OriginalCallerSourceAdmission::backing_work_demand(),|e|RetainedWorkPoll::Complete(source.admit_backing(e)))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("failed Source allocation pending")};assert_eq!(attempts,1);assert_eq!(actual,Some(0));assert_eq!(heap,(0,0));assert_eq!(turn.result.unwrap_err().kind,ValueRefusalKind::AllocationFailed);assert_eq!(bank.wallet().remaining(),remaining);assert_eq!(bank.wallet().remaining_work(),work_before-u64::try_from(turn.work).unwrap());assert_eq!(bank.take_admitted(),Some(true));assert_eq!(source.has_roots(),law[1]["original"].as_bool().unwrap());assert!(!source.has_backing());assert_eq!(source.payload_identity(),Some(payload_identity));assert_eq!(source.cancellation_identity(),Some(cancel_identity));
 step(&mut bank,OriginalCallerSourceAdmission::prepare_demand(),1,|e|source.return_inputs(&mut authority,&mut token,e));assert!(source.terminal_is_empty());assert_eq!(authority.as_ref().unwrap().identity(),Some(payload_identity));assert_eq!(OriginalCancelRootAdmission::token_identity(token.as_ref().unwrap()),cancel_identity);for _ in 0..16{let original=authority.as_mut().unwrap();if original.terminal_is_empty(){break}let demand=original.retirement_demands();let work=original.retirement_work_demand().unwrap();step(&mut bank,demand,work,|e|original.close_step(e));}assert!(authority.as_ref().unwrap().terminal_is_empty());
 let mut retired=None;let demand=RetirementDemand{copy_bytes:std::mem::size_of::<Option<CancelToken>>()+std::mem::size_of::<Option<semio_framework_async::CancelTokenRetirement>>(),depth:1,..Default::default()};step(&mut bank,demand,1,|e|{assert!(e.performed(1).unwrap());retired=Some(semio_framework_async::CancelTokenRetirement::from_token(token.take().unwrap()));RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})),work:1}});for _ in 0..16{let original=retired.as_mut().unwrap();if original.terminal_is_empty(){break}let demand=original.retirement_demands().unwrap();let work=original.retirement_work_demand();let issued=grant(demand);let((poll,actual),heap)=observe(||bank.run(issued,work,|e|RetainedWorkPoll::Complete(original.close_step(e))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("cancellation close pending")};assert_eq!(actual,None);bank.post(turn.result.unwrap().progress(),issued,heap);assert_eq!(bank.take_admitted(),Some(true));}assert!(retired.as_ref().unwrap().terminal_is_empty());
}
